export function handleCreateByLoginPassword(body) {
  return api.post(
    'sign_up',
    body,
    'CREATE_USER',
    dispatch
  )
}

export function handleResetPassword(body) {
  return api.post(
    'user/password/reset',
    body,
    'RESET_PASSWORD',
    dispatch
  )
}

export function handleSendCode(body) {
  return api.post(
    'user/password/forgot',
    body,
    'SEND_CODE',
    dispatch
  )
}

export function handlePKCS7Auth(pkcs7) {
  return api.post(
    'authorise/x509',
    { pkcs7 },
    'PKCS7_AUTH',
    dispatch
  );
}
